export const App: React.FC = () => {
  const [step, setStep] = useState<AppStep>(AppStep.LANDING);
  const [formData, setFormData] = useState<FormData>(INITIAL_DATA);
  const [geminiResult, setGeminiResult] = useState<string>("");
  const [isAutofilling, setIsAutofilling] = useState(false);
  const [uploadedAssets, setUploadedAssets] = useState<{
    char: Array<File | null>;
    logo: Array<File | null>;
    ref: Array<File | null>;
    attr: Array<File | null>;
  }>({
    char: [null, null, null],
    logo: [null, null, null],
    ref: [null, null, null],
    attr: [null, null, null],
  });
  const [copiedId, setCopiedId] = useState<string | number | null>(null);

  const { language, t } = useLanguage();
  const {
    genderLabels,
    targetAudienceLabels,
    visualStyleLabels,
    visualThemeLabels,
    carouselTypeLabels,
    platformLabels, 
    languageStyleLabels, 
    posterLayoutTypeLabels, 
    comicContentTypeLabels,
    storyFlowLabels, 
    comicEmotionLabels, 
  } = getTranslatedLabels(language);

  const updateData = (key: keyof FormData, value: any) => setFormData(prev => ({ ...prev, [key]: value }));
  const handleAdditionalElementChange = (key: keyof FormData['additionalElements'], value: boolean) => {
    setFormData(prev => ({
      ...prev,
      additionalElements: {
        ...prev.additionalElements,
        [key]: value,
      },
    }));
  };

  const handleAssetFilesChange = (category: string, files: Array<File | null>) => {
    setUploadedAssets(prev => ({
      ...prev,
      [category]: files,
    }));
  };

  const handleCopy = (text: string, id: string | number) => {
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const isCarousel = formData.mode === PosterMode.CAROUSEL;
  const isComicStrip = formData.mode === PosterMode.COMIC_STRIP;

  const handlePresetChange = (presetKey: string) => {
    updateData('preset', presetKey);
    if (presetKey && PRESET_LIBRARY[presetKey]) {
      setFormData(prev => ({ ...prev, ...PRESET_LIBRARY[presetKey], preset: presetKey }));
      setUploadedAssets({
        char: [null, null, null],
        logo: [null, null, null],
        ref: [null, null, null],
        attr: [null, null, null],
      });
    }
  };


  const autoFill = async (context: any = 'topic') => {
    setIsAutofilling(true);
    try {
      const generatedData = await generateAutoFillContent(
        formData.mode || PosterMode.COMIC_STRIP,
        { 
          ...formData, 
          targetAudience: formData.targetAudience as TargetAudience, 
          carouselType: formData.carouselType as CarouselType,
          platform: formData.platform as Platform, 
          languageStyle: formData.languageStyle as LanguageStyle, 
          posterLayoutType: formData.posterLayoutType as PosterLayoutType, 
          additionalElements: formData.additionalElements, 
          ctaActive: formData.ctaActive, 
          funFactActive: formData.funFactActive, 
          funFact: formData.funFact, 
        }, 
        context
      );
      if (generatedData) {
        if (context === 'funFact') {
          updateData('funFact', generatedData.funFact || '');
        } else if (context === 'cta') {
          updateData('cta', generatedData.cta || '');
        } else {
          setFormData(prev => ({ ...prev, ...generatedData }));
        }
      }
    } catch (e) {
      console.error(e);
      if (isComicStrip) {
        if (context === 'topic') updateData('topic', 'Petualangan');
        if (context === 'title') updateData('title', 'Kisah Hebat');
        if (context === 'subtitle') updateData('subtitle', 'Petualangan Seru'); 
        if (context === 'material') updateData('material', 'Panel 1: Tokoh utama bertemu teman baru\nPanel 2: Mereka menghadapi tantangan\nPanel 3: Bekerja sama mengatasi masalah');
        if (context === 'cta' && formData.ctaActive) updateData('cta', 'Baca kisah selengkapnya!');
        updateData('visualTheme', 'Ceria, warna-warni, gaya kartun');
        updateData('size', AspectRatio.R_16_9);
        updateData('comicContentType', ComicContentType.COMIC); 
      } else if (isCarousel) {
        if (context === 'topic') updateData('topic', 'Pendidikan Umum');
        if (context === 'title') updateData('title', 'Belajar Seru');
        if (context === 'subtitle') updateData('subtitle', 'Konten Interaktif');
