        updateData('languageStyle', formData.languageStyle || LanguageStyle.RELAXED); 
        updateData('posterLayoutType', formData.posterLayoutType || PosterLayoutType.EDUCATIONAL_POSTER);
        updateData('size', AspectRatio.R_1_1);
        updateData('visualTheme', 'Modern, Bersih, Penuh Warna');
