      let visualStylePrompt = visualStyleLabels[formData.visualStyle as VisualStyle] || formData.visualStyle;

      let visualDescription = '';
      const additionalPromptInstructions = formData.additionalPrompt; 

      if (currentVisualThemeKey === '3d_soft_clay') {
        let audienceAdaptation = '';
        switch (formData.targetAudience) {
          case TargetAudience.PAUD:
