            audienceAdaptation = 'Characters in chibi proportions, simple expressions, bright pastel colors, very playful illustration.';
            break;
          case TargetAudience.SD_UPPER:
          case TargetAudience.SMP:
            audienceAdaptation = 'Rounded shapes, cleaner and more informative, slightly less playful.';
            break;
          case TargetAudience.SMA:
          case TargetAudience.TEACHER:
          case TargetAudience.ADULT:
          case TargetAudience.GEN_Z:
            audienceAdaptation = 'More minimalist clay style, softer or muted colors, cleaner composition.';
            break;
          default:
            audienceAdaptation = ''; 
        }

        visualDescription = `3D Soft Clay / Plush Illustration style. Objects are rounded, soft, and lack sharp angles, resembling clay, plasticine, or plush toys (not fabric/knitted). Smooth surfaces without fabric textures. Soft, diffuse lighting. Friendly, warm, visually safe aesthetic. Decorative stitching accents (not actual fabric texture). ${audienceAdaptation} Avoid real fabric, knit, or harsh geometric shapes. Use light 3D depth with subtle shadows. Maintain style consistency across all elements.`;
      } 
