import { GoogleGenAI, Type } from "@google/genai";
import { FormData, PosterMode, AspectRatio, TargetAudience, VisualStyle, CarouselType, Platform, LanguageStyle, PosterLayoutType, ComicContentType } from "../types";
import { translations } from "../translations";

export interface SequentialPrompt {
  title: string;
  content: string;
}

// Helper to sanitize JSON string
const cleanJsonString = (str: string) => {
  return str.replace(/```json\n?|```/g, '').trim();
};

// Helper to convert camelCase to snake_case for translation keys
const camelCaseToSnakeCase = (name: string) => {
  return name.replace(/([A-Z])/g, '_$1').toLowerCase();
};

/**
 * Generates a list of unique, sequential prompts based on user input.
 * Each slide produces a separate, detailed JSON prompt.
 */
export const generateSequentialPrompts = async (formData: FormData): Promise<SequentialPrompt[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const slideCount = parseInt(formData.slideCount || '5');
  const isComic = formData.mode === PosterMode.COMIC_STRIP;

  const prompt = `
    You are an expert AI Prompt Architect for ${formData.mode} creation.
    Task: Generate exactly ${slideCount} separate, unique, and sequential prompts.

    Format: Return a JSON array of ${slideCount} objects. Each object has:
    - "title": (String) Indonesian title, e.g., "Halaman 1 - Cover Komik", "Halaman 2 - Isi", etc.
    - "content": (String) A detailed JSON string exactly matching the schema below.

    SCHEMA FOR "content" FIELD (Stringified JSON):
    {
      "slide_ke": number,
      "jenis_halaman": string (e.g., "Cover Komik", "Isi Komik", "Penutup Komik"),
      "tipe_konten": "${formData.mode}",
      "alur_cerita": "${isComic ? formData.storyFlow : ''}",
      "unsur_emosi": "${isComic ? formData.emotionalElements : ''}",
      "target_audiens": "${formData.targetAudience}",
      "rasio": "${formData.size}",
      "mode_visual": "${formData.visualStyle}",
      "tema_gaya": "${formData.visualTheme}",
      "topik_materi": "${formData.topic}",
      "judul_utama": "${formData.title}",
      "sub_judul": "${formData.subtitle}",
      "isi_materi": string (Specific text for THIS slide based on: ${formData.material}),
      "deskripsi_visual": string (Detailed visual prompt in English for AI image generators),
      "panel_komik": {
        "jumlah_panel": number,
        "fungsi": string
      },
      "identitas_pembuat": "${formData.socialAccount}",
      "watermark": "${formData.watermark}"
    }

    SPECIFIC RULES:
    1. SLIDE 1 (COVER): Must focus on the title/branding. "jumlah_panel" is 1. "fungsi" is "Cover utama".
    2. SEQUENTIAL FLOW: Slides 2 to ${slideCount - 1} must follow the story/material logic sequentially.
    3. FINAL SLIDE: Must be a conclusion or CTA.
    4. NO DUPLICATES: Each slide must have a unique "deskripsi_visual" and "isi_materi".
    5. LANGUAGE: Content of "deskripsi_visual" should be in English for better AI image generation results. Other fields in Indonesian.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ text: prompt }],
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              content: { type: Type.STRING }
            },
            required: ['title', 'content']
          }
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Error generating sequential prompts:", error);
    return Array.from({ length: slideCount }, (_, i) => ({
      title: `Halaman ${i + 1}`,
      content: JSON.stringify({
        slide_ke: i + 1,
        judul_utama: formData.title,
        deskripsi_visual: `Detailed prompt for ${formData.topic} in ${formData.visualStyle} style.`
      }, null, 2)
    }));
  }
};

export const generateAutoFillContent = async (
  mode: PosterMode | string, 
  currentValues: { 
    topic: string; 
    title: string; 
    subtitle: string; 
    material: string; 
    cta: string;
    targetAudience?: TargetAudience; 
    carouselType?: CarouselType; 
    platform?: Platform | string;
    languageStyle?: LanguageStyle | string;
    posterLayoutType?: PosterLayoutType | string;
    additionalElements?: { [key: string]: boolean };
    ctaActive: boolean; 
    funFact: string; 
    funFactActive: boolean; 
    storyFlow?: string; 
    emotionalElements?: string; 
    comicContentType?: ComicContentType;
    slideCount?: string;
  }, 
  context: 'topic' | 'title' | 'subtitle' | 'material' | 'cta' | 'funFact' = 'topic'
): Promise<Partial<FormData>> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  let prompt = "";
  const isCarouselMode = mode === PosterMode.CAROUSEL;
  const isComicStripMode = mode === PosterMode.COMIC_STRIP;
  const currentLanguage = 'id'; 
  const t = (key: keyof typeof translations['id']) => {
    return translations[currentLanguage][key] || key;
  };

  if (context === 'funFact') {
    const topic = currentValues.topic?.trim();
    let funFactPrompt = "";
    if (topic) {
      funFactPrompt = t('ph_fun_fact_topic_auto_fill').replace('{topic}', topic);
    } else {
      funFactPrompt = t('ph_fun_fact_default_auto_fill');
    }
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{text: funFactPrompt}],
    });
    return { funFact: response.text };
  }

  // Dedicated Material Generation for Carousel
  if (isCarouselMode && context === 'material') {
    let additionalElementsText = '';
    if (currentValues.additionalElements) {
      const activeElements = Object.keys(currentValues.additionalElements)
        .filter(key => currentValues.additionalElements?.[key]);
      if (activeElements.length > 0) {
        additionalElementsText = ` (Include elements: ${activeElements.map(key => t(`checkbox_${camelCaseToSnakeCase(key)}` as keyof typeof translations['id'])).join(', ')})`;
      }
    }

    prompt = `
      You are an AI CONTENT ARCHITECT specialized in high-conversion educational and commercial carousels for ${currentValues.platform || 'social media'}.
      Task: Generate the sequential "ISI MATERI" (script) for a carousel post.

      CONTEXTUAL INPUTS:
      - Topic: "${currentValues.topic || 'General Education'}"
      - Main Title: "${currentValues.title || 'Educational Content'}"
      - Subtitle: "${currentValues.subtitle || 'Learn More'}"
      - Carousel Type: "${currentValues.carouselType || 'Edukasi'}"
      - Poster Type: "${currentValues.posterLayoutType || 'Poster Edukasi'}"
      - Platform: "${currentValues.platform || 'Instagram'}"
      - Language Style: "${currentValues.languageStyle || 'Santai'}"
      - Target Audience: "${currentValues.targetAudience || 'Umum'}"
      - Slide Count: "${currentValues.slideCount || '5 Slides'}" (STRICT: Generate exactly this many blocks)
      ${additionalElementsText}

      GENERATION RULES:
      1. NARRATIVE FLOW: Follow a clear logical progression:
         - Slide 1: HOOK (Attention-grabbing intro linked to title).
         - Slides 2 to (N-1): SUBSTANCE (Deep dive into topic, unique points, sequential teaching).
         - Final Slide: CONCLUSION/CTA (Call to action & wrap up).
      2. TONE & AUDIENCE: Use language style "${currentValues.languageStyle}" appropriate for audience "${currentValues.targetAudience}".
      3. NO REPETITION: Every slide must offer new information or a specific step in the process.
      4. CONNECTIVITY: Ensure a smooth transition between slides (swipe-friendly logic).
      5. FORMAT: Plain text numbered list (Slide 1: ..., Slide 2: ...).

      GENERATE SEQUENTIAL CAROUSEL CONTENT:
    `;
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{text: prompt}],
    });
    return { material: response.text };
  }

  // Dedicated Material Generation for Comic Strip
  if (isComicStripMode && context === 'material') {
    prompt = `
      You are an AI SCRIPTWRITER for educational and commercial comics.
      Task: Generate the sequential "ISI MATERI" (story content) for a ${currentValues.comicContentType || 'Comic'}.

      CONTEXTUAL INPUTS:
      - Topic: "${currentValues.topic || 'General Education'}"
      - Main Title: "${currentValues.title || 'Educational Story'}"
      - Story Flow Type: "${currentValues.storyFlow || 'Slice of Life'}"
      - Key Emotions: "${currentValues.emotionalElements || 'Curious'}"
      - Slide/Panel Count: "${currentValues.slideCount || '5 Slides'}" (STRICT: Generate exactly this many distinct steps)
      - Target Audience: "${currentValues.targetAudience || 'SD Kelas Rendah'}"

      GENERATION RULES:
      1. SCRIPT STRUCTURE: Use a sequential numbering format (e.g., Panel 1: ..., Panel 2: ...).
      2. NARRATIVE ARC: Ensure a clear beginning, middle, and end that connects seamlessly across all panels.
      3. TONE & EMOTION: Infuse the content with "${currentValues.emotionalElements}" and follow the rhythm of "${currentValues.storyFlow}".
      4. AUDIENCE ADAPTATION: Language must be appropriate for "${currentValues.targetAudience}".
      5. NO REPETITION: Each panel must present new information or a progression in the story.
      6. CONTENT FOCUS: If educational, explain the topic through dialogue or action. If commercial, lead naturally to a product/service showcase.
      7. OUTPUT FORMAT: Plain text, bulleted or numbered list of panels. No technical JSON code.

      GENERATE SEQUENTIAL COMIC CONTENT:
    `;
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{text: prompt}],
    });
    return { material: response.text };
  }

  let responseMimeType: string | undefined = 'application/json'; 
  let logicInstruction = "";
  let requiredFieldsArray: string[] = []; 
  let requiredFields: string = ''; 
  const carouselMaterialGuidance = isCarouselMode ? ` (The 'material' field must contain exactly ${currentValues.slideCount || '5'} sequential content blocks (e.g., Slide 1: ..., Slide 2: ...). It must follow the '${currentValues.carouselType}' flow, use '${currentValues.languageStyle}' tone, and be tailored for '${currentValues.targetAudience}'. Ensure a logical connection between slides with NO repetition of points.)` : ``;
  const comicGuidance = isComicStripMode ? ` (The 'material' field must be a sequential story structure (e.g. Panel 1, Panel 2...) following the '${currentValues.storyFlow}' flow and '${currentValues.emotionalElements}' emotions for '${currentValues.slideCount}' panels.)` : ``;

  let carouselContextFields = '';
  if (isCarouselMode) {
    carouselContextFields = `
      Platform: "${currentValues.platform || 'Instagram Carousel'}"
      Language Style: "${currentValues.languageStyle || LanguageStyle.RELAXED}"
      Poster Layout Type: "${currentValues.posterLayoutType || 'Poster Edukasi'}"
      Carousel Type: "${currentValues.carouselType || 'Edukasi'}"
      Slide Count: "${currentValues.slideCount || '5 Slides'}"
    `;
  }

  const addField = (fieldName: string, condition: boolean = true) => {
    if (condition) {
      requiredFieldsArray.push(`"${fieldName}"`);
    }
  };

  if (context === 'title') {
    logicInstruction = `
      CONTEXT: The user wants a new Title based on the Topic: "${currentValues.topic || 'General'}".
      CASCADE LOGIC: 
      1. LOCKED: Topic is "${currentValues.topic}".
      2. GENERATE: New Creative "title" based on Topic.
      3. GENERATE: New "subtitle" that matches the new Title.
      4. GENERATE: New "material" that matches the new Title.${carouselMaterialGuidance}${comicGuidance}
      5. If Comic mode, generate "storyFlow" and "emotionalElements" if empty.
      6. If CTA is active, generate a new "cta".
      7. If Fun Fact is active, generate a new "funFact".
    `;
    addField('title');
    addField('subtitle');
    addField('material');
    addField('storyFlow', isComicStripMode);
    addField('emotionalElements', isComicStripMode);
    addField('cta', currentValues.ctaActive);
    addField('funFact', currentValues.funFactActive);
  } else if (context === 'subtitle') {
    logicInstruction = `
      CONTEXT: The user wants a new Subtitle. 
      CASCADE LOGIC:
      1. LOCKED: Topic is "${currentValues.topic}".
      2. LOCKED: Title is "${currentValues.title}".
      3. GENERATE: New "subtitle" that compliments the existing Title.
      4. GENERATE: New "material" that fits this specific Title & Subtitle combination.${carouselMaterialGuidance}${comicGuidance}
      5. If CTA is active, generate a new "cta".
    `;
    addField('subtitle');
    addField('material');
    addField('cta', currentValues.ctaActive);
  } else if (context === 'material') { 
    logicInstruction = `
      CONTEXT: The user wants new Content/Material only.
      GENERATE: New "material" content.${carouselMaterialGuidance}${comicGuidance}
    `;
    addField('material');
    addField('cta', currentValues.ctaActive);
  } else if (context === 'cta') {
    logicInstruction = `
      CONTEXT: The user wants a new Call To Action (CTA).
      GENERATE: New creative "cta" based on the overall content.
    `;
    addField('cta');
  } else { 
    logicInstruction = `
      CONTEXT: The user wants a new Topic, and other fields should follow.
      CASCADE LOGIC:
      1. GENERATE: New "topic".
      2. GENERATE: New creative "title" based on the new Topic.
      3. GENERATE: New "subtitle" that matches the new Title.
      4. GENERATE: New "material" that matches the new Title and Subtitle.${carouselMaterialGuidance}${comicGuidance}
      5. If Comic mode, generate "storyFlow" and "emotionalElements".
      6. If CTA is active, generate a new "cta".
      7. If Fun Fact is active, generate a new "funFact".
    `;
    addField('topic');
    addField('title');
    addField('subtitle');
    addField('material');
    addField('storyFlow', isComicStripMode);
    addField('emotionalElements', isComicStripMode);
    addField('cta', currentValues.ctaActive);
    addField('funFact', currentValues.funFactActive);
  }

  requiredFields = requiredFieldsArray.join(', ');

  prompt = `
