    const parsed = JSON.parse(jsonStr);
    return parsed;
  } catch (e) {
    console.error("Failed to parse JSON from AI response:", e, "Raw response:", jsonStr);
    return {};
  }
};

import { GoogleGenAI, Type } from "@google/genai";
import { FormData, PosterMode, AspectRatio, TargetAudience, VisualStyle, CarouselType, Platform, LanguageStyle, PosterLayoutType, ComicContentType } from "../types";
import { translations } from "../translations";

export interface SequentialPrompt {
  title: string;
  content: string;
}

// Helper to sanitize JSON string
const cleanJsonString = (str: string) => {
  return str.replace(/```json\n?|```/g, '').trim();
};

// Helper to convert camelCase to snake_case for translation keys
const camelCaseToSnakeCase = (name: string) => {
  return name.replace(/([A-Z])/g, '_$1').toLowerCase();
};

/**
 * Generates a list of unique, sequential prompts based on user input.
 * Adheres strictly to the structural requirements for Cover (Slide 1), 
 * Pembukaan (Slide 2), and Inti Cerita (Slide 3 to N-1).
 */
export const generateSequentialPrompts = async (formData: FormData): Promise<SequentialPrompt[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const slideCountString = formData.slideCount || '5';
  const slideCount = parseInt(slideCountString.split(' ')[0]) || 5;
  const isComic = formData.mode === PosterMode.COMIC_STRIP;

  const prompt = `
    You are a professional Prompt Engineer and Scriptwriter for Educational Comics.
    Task: Generate exactly ${slideCount} separate, unique, and sequential prompts in JSON format.

    PROJECT CONTEXT:
    - Mode: "${formData.mode}"
    - Topic: "${formData.topic}"
    - Title: "${formData.title}"
    - Subtitle: "${formData.subtitle}"
    - Material/Script: "${formData.material}"
    - Target Audience: "${formData.targetAudience}"
    - Style: "${formData.visualStyle}" (${formData.visualTheme})
    - Flow: "${formData.storyFlow}", Emotion: "${formData.emotionalElements}"
    - Character Settings: ${formData.showCharacter ? `Gender: ${formData.gender}, Hijab: ${formData.hijab}, Niqab: ${formData.niqab}` : 'No human character'}

    OUTPUT RULES:
    Return a JSON array of ${slideCount} objects. Each object has:
    - "title": (String) Indonesian title for the card.
    - "content": (String) A stringified JSON object matching the specific page type rules below.

    1. RULES FOR SLIDE 1 (COVER):
    - jenis_halaman: "Cover Komik"
    - jumlah_panel: 1
    - fungsi: "Cover utama tanpa narasi panjang"
    - deskripsi_visual: "Ilustrasi cover komik dengan komposisi kuat dan fokus utama pada judul. Visual menarik, ekspresif, dan sesuai target audiens."

    2. RULES FOR SLIDE 2 (PEMBUKAAN):
    - jenis_halaman: "Isi Komik - Pembukaan"
    - jumlah_panel: 3
    - detail_panel: [ "Panel 1: Pengenalan situasi", "Panel 2: Aksi atau kejadian awal", "Panel 3: Pemicu cerita" ]
    - deskripsi_visual: "Halaman pembuka isi komik yang memperkenalkan situasi awal sesuai alur cerita."

    3. RULES FOR SLIDES 3 TO ${slideCount - 1} (INTI CERITA):
    - jenis_halaman: "Isi Komik - Inti Cerita"
    - jumlah_panel: 3
    - detail_panel: [ "Panel 1: Proses atau konflik", "Panel 2: Reaksi karakter", "Panel 3: Penegasan pesan" ]
    - deskripsi_visual: "Halaman inti komik yang menyampaikan pesan utama atau konflik cerita."

    4. RULES FOR SLIDE ${slideCount} (PENUTUP):
    - jenis_halaman: "Isi Komik - Penutup"
    - fokus: Resolution or Call to Action.

    GENERAL SCHEMA FOR ALL "content" STRINGS:
    {
      "slide_ke": number,
      "jenis_halaman": string,
      "tipe_konten": "Komik",
      "alur_cerita": "${formData.storyFlow}",
      "unsur_emosi": "${formData.emotionalElements}",
      "target_audiens": "${formData.targetAudience}",
      "rasio": "${formData.size}",
      "mode_visual": "${formData.visualStyle}",
      "tema_gaya": "${formData.visualTheme}",
      "topik_materi": "${formData.topic}",
      "judul_utama": "${formData.title}",
      "sub_judul": "${formData.subtitle}",
      "isi_materi": "Indonesian script text for this page...",
      "deskripsi_visual": "English visual description for AI...",
      "panel_komik": {
        "jumlah_panel": number,
        "fungsi": string (optional for cover),
        "detail_panel": string[] (optional for cover)
      },
      "identitas_pembuat": "${formData.socialAccount}",
      "watermark": "${formData.watermark}"
    }

    STRICT: Use Indonesian for text fields except for technical AI prompts inside "deskripsi_visual" and "detail_panel", which MUST be in English.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ text: prompt }],
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              content: { type: Type.STRING }
            },
            required: ['title', 'content']
          }
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Error generating sequential prompts:", error);
    return Array.from({ length: slideCount }, (_, i) => ({
      title: `Halaman ${i + 1}`,
      content: JSON.stringify({
        slide_ke: i + 1,
        judul_utama: formData.title,
        deskripsi_visual: `High quality educational comic of ${formData.topic}. (API Error Fallback)`
      }, null, 2)
    }));
  }
};

