      5. If Comic mode, generate "storyFlow" and "emotionalElements" if empty.
      6. If CTA is active, generate a new "cta".
      7. If Fun Fact is active, generate a new "funFact".
    `;
    addField('title');
    addField('subtitle');
    addField('material');
    addField('storyFlow', isComicStripMode);
    addField('emotionalElements', isComicStripMode);
    addField('cta', currentValues.ctaActive);
    addField('funFact', currentValues.funFactActive);
  } else if (context === 'subtitle') {
