            "detail_panel": string[] (Detailed English description for each panel)
          },
          "identitas_pembuat": "${formData.socialAccount}",
          "watermark": "${formData.watermark}"
        }
    `;
  } else {
    // CAROUSEL MODE - Updated based on latest user request
    const activeElements = Object.keys(formData.additionalElements)
      .filter(key => formData.additionalElements[key as keyof typeof formData.additionalElements])
      .join(', ');

    systemInstruction = `
      You are a Professional Content Strategist and Carousel Designer.
      Task: Generate exactly ${slideCount} sequential slides for a CAROUSEL.
      Format: JSON array of ${slideCount} objects. Each object contains "title" (ID) and "content" (stringified JSON).

      CAROUSEL RULES:
      - Slide 1 is ALWAYS "Cover Carousel".
      - Slides 2 to (N-1) are "Isi Carousel".
      - Slide N is "Penutup Carousel".

      Schema for "content" (MANDATORY):
      {
