export const generateAutoFillContent = async (
  mode: PosterMode | string, 
  currentValues: { 
    topic: string; 
    title: string; 
    subtitle: string; 
    material: string; 
    cta: string;
    targetAudience?: TargetAudience | string; 
    carouselType?: CarouselType; 
    platform?: Platform | string;
    languageStyle?: LanguageStyle | string;
    posterLayoutType?: PosterLayoutType | string;
    additionalElements?: { [key: string]: boolean };
    ctaActive: boolean; 
    funFact: string; 
    funFactActive: boolean; 
    storyFlow?: string; 
    emotionalElements?: string; 
    comicContentType?: ComicContentType;
    slideCount?: string;
  }, 
  context: 'topic' | 'title' | 'subtitle' | 'material' | 'cta' | 'funFact' = 'topic',
  language: Language = 'id'
): Promise<Partial<FormData>> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const t = (key: keyof typeof translations['id']) => {
    return (translations[language] as any)?.[key] || translations['id'][key] || key;
  };

  if (context === 'funFact') {
    const topic = currentValues.topic?.trim();
    let funFactPrompt = "";
    if (topic) {
      funFactPrompt = t('ph_fun_fact_topic_auto_fill').replace('{topic}', topic);
    } else {
      funFactPrompt = t('ph_fun_fact_default_auto_fill');
    }

    // Explicitly tell Gemini to respond in the user's language
    const langName = language === 'id' ? 'Indonesian' : 'the user\'s selected language';
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ text: `${funFactPrompt}. Please respond in ${langName} only.` }],
    });
    return { funFact: response.text };
  }

  const isCarouselMode = mode === PosterMode.CAROUSEL;
  const isComicStripMode = mode === PosterMode.COMIC_STRIP;

  let prompt = `
    You are an AI CONTENT ENGINE. Generate creative content for ${mode}.
    Language: Please respond in ${language === 'id' ? 'Indonesian' : 'English'} only.

    Context:
    - Topic: "${currentValues.topic}"
    - Current Title: "${currentValues.title}"
    - Audience: "${currentValues.targetAudience}"

    Task: Update the field [${context}].
  `;

  // Material generation logic
  if (context === 'material') {
      if (isCarouselMode) {
          prompt += ` Generate a sequential script for ${currentValues.slideCount || '5'} slides. Follow a ${currentValues.carouselType} structure.`;
      } else if (isComicStripMode) {
          prompt += ` Generate a sequential comic script for ${currentValues.slideCount || '5'} panels. Follow a ${currentValues.storyFlow} flow with ${currentValues.emotionalElements} emotions.`;
      }
  }

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [{text: prompt}],
    config: {
      responseMimeType: 'application/json',
      responseSchema: {
          type: Type.OBJECT,
          properties: {
              [context]: { type: Type.STRING }
          },
          required: [context]
      }
    }
  });

  try {
    return JSON.parse(cleanJsonString(response.text));
  } catch (e) {
    console.error("Failed to parse JSON:", e);
    return {};
  }
};

