            "Panel 3: Description in ${targetLang}"
          ]
        }
      }

      FINAL SLIDE SCHEMA:
      {
        "slide_ke": ${slideCount},
        "jenis_halaman": "Isi Komik - Penutup",
        "tipe_konten": "Komik",
        "isi_materi": "Conclusion in ${targetLang}..."
        ...
      }
    `;
  } else {
    // CAROUSEL MODE
    const activeElements = Object.keys(formData.additionalElements)
      .filter(key => formData.additionalElements[key as keyof typeof formData.additionalElements])
      .join(', ');

    systemInstruction = `
      You are a Professional Carousel Designer.
      Task: Generate exactly ${slideCount} sequential slides for a CAROUSEL.
      Format: JSON array of ${slideCount} objects. Each object contains "title" and "content" (stringified JSON).

      CAROUSEL SCHEMA (MANDATORY FOR ALL SLIDES):
      {
        "slide_ke": number,
        "jenis_slide": "Cover Carousel" | "Isi Carousel" | "Penutup Carousel",
        "platform": "${formData.platform}",
        "jumlah_slide": "${formData.slideCount}",
        "gaya_bahasa": "${formData.languageStyle}",
        "tipe_poster": "${formData.posterLayoutType}",
        "target_audiens": "${formData.targetAudience}",
        "topik_materi": "${formData.topic}",
        "judul_utama": "${formData.title}",
        "sub_judul": "${formData.subtitle}",
        "isi_materi": "Specific ${targetLang} text for this slide...",
        "call_to_action": "${formData.ctaActive ? formData.cta : ''}",
        "fun_fact": "${formData.funFactActive ? formData.funFact : ''}",
        "identitas_pembuat": "${formData.socialAccount}",
        "watermark": "${formData.watermark}",
        "ukuran_kertas": "${formData.size}",
        "mode_visual": "${formData.visualStyle}",
        "tema_gaya": "${formData.visualTheme}",
        "elemen_tambahan": "${activeElements}",
        "instruksi_tambahan": "${formData.additionalPrompt}"
      }
    `;
  }

  const prompt = `
    ${systemInstruction}

    Current Context:
    - Topic: "${formData.topic}"
    - Title: "${formData.title}"
    - Material Script: "${formData.material}"

    CRITICAL LANGUAGE RULE:
    - All creative text fields (judul_utama, sub_judul, isi_materi, fun_fact, call_to_action) MUST be in ${targetLang}.
    - Only technical AI image prompts (deskripsi_visual, deskripsi_visual_utama) should be in English.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ text: prompt }],
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              content: { type: Type.STRING }
            },
            required: ['title', 'content']
          }
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Error generating sequential prompts:", error);
    return Array.from({ length: slideCount }, (_, i) => ({
      title: `Slide ${i + 1}`,
      content: JSON.stringify({ slide_ke: i + 1, judul_utama: formData.title }, null, 2)
    }));
  }
};

export const generateAutoFillContent = async (
  mode: PosterMode | string, 
  currentValues: { 
    topic: string; 
    title: string; 
    subtitle: string; 
    material: string; 
    cta: string;
    targetAudience?: TargetAudience | string; 
    carouselType?: CarouselType; 
    platform?: Platform | string;
    languageStyle?: LanguageStyle | string;
    posterLayoutType?: PosterLayoutType | string;
    additionalElements?: { [key: string]: boolean };
    ctaActive: boolean; 
    funFact: string; 
    funFactActive: boolean; 
    storyFlow?: string; 
    emotionalElements?: string; 
    comicContentType?: ComicContentType;
    slideCount?: string;
  }, 
  context: 'topic' | 'title' | 'subtitle' | 'material' | 'cta' | 'funFact' = 'topic',
  language: Language = 'id'
): Promise<Partial<FormData>> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const t = (key: keyof typeof translations['id']) => {
    return (translations[language] as any)?.[key] || translations['id'][key] || key;
  };

  const targetLang = langNames[language] || 'Indonesian';

  if (context === 'funFact') {
    const topic = currentValues.topic?.trim();
    let basePrompt = "";
    if (topic) {
      basePrompt = t('ph_fun_fact_topic_auto_fill').replace('{topic}', topic);
    } else {
      basePrompt = t('ph_fun_fact_default_auto_fill');
    }

    // Explicitly demand response in the target language
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ text: `${basePrompt}. MANDATORY: Respond with the fun fact text ONLY in ${targetLang} language.` }],
    });
    return { funFact: response.text };
  }

  const isCarouselMode = mode === PosterMode.CAROUSEL;
  const isComicStripMode = mode === PosterMode.COMIC_STRIP;

  let prompt = `
    You are an AI CONTENT ENGINE. Your task is to auto-fill the field [${context}] for a ${mode} project.
    MANDATORY LANGUAGE: All generated content MUST be in ${targetLang}.

    Context:
    - Topic: "${currentValues.topic}"
    - Current Title: "${currentValues.title}"
    - Target Audience: "${currentValues.targetAudience}"
    - Mode specific info: ${isCarouselMode ? `Carousel Type: ${currentValues.carouselType}, Slides: ${currentValues.slideCount}` : `Story Flow: ${currentValues.storyFlow}, Emotion: ${currentValues.emotionalElements}`}
  `;

  if (context === 'material') {
      if (isCarouselMode) {
          prompt += ` Generate a sequential script for ${currentValues.slideCount || '5'} slides using a ${currentValues.carouselType} structure.`;
      } else if (isComicStripMode) {
          prompt += ` Generate a sequential comic script for ${currentValues.slideCount || '5'} panels/pages. Follow a ${currentValues.storyFlow} flow with ${currentValues.emotionalElements} emotions.`;
      }
  }

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [{text: prompt}],
    config: {
      responseMimeType: 'application/json',
      responseSchema: {
          type: Type.OBJECT,
          properties: {
              [context]: { type: Type.STRING, description: `The creative content for the ${context} field in ${targetLang}.` }
          },
          required: [context]
      }
    }
  });

  try {
    return JSON.parse(cleanJsonString(response.text));
  } catch (e) {
    console.error("Failed to parse JSON:", e);
    return {};
  }
};

