// Updated UploadBox component to handle multiple file previews and removal
interface UploadBoxProps {
  title: string;
  category: string;
  files: Array<File | null>;
  onFilesChange: (category: string, files: Array<File | null>) => void;
}

const UploadBox: React.FC<UploadBoxProps> = ({ title, category, files, onFilesChange }) => {
  const { t } = useLanguage();
  const fileInputRefs = useRef<(HTMLInputElement | null)[]>([]);

  // State to store object URLs associated with files for proper cleanup
  const [fileObjectUrls, setFileObjectUrls] = useState<Array<string | null>>(files.map(file => file ? URL.createObjectURL(file) : null));

  // Update object URLs when the `files` prop changes from the parent
  useEffect(() => {
    setFileObjectUrls(prevUrls => {
      const newUrls: (string | null)[] = [];
      const urlsToRevoke: string[] = [...prevUrls.filter(Boolean) as string[]]; 

      files.forEach((file, index) => {
        if (file) {
          const oldFileIndex = files.findIndex((oldFile, oldIdx) => oldFile === file && prevUrls[oldIdx] !== null);
          if (oldFileIndex !== -1) {
            newUrls[index] = prevUrls[oldFileIndex];
            const revokeIndex = urlsToRevoke.indexOf(prevUrls[oldFileIndex]!);
            if (revokeIndex > -1) urlsToRevoke.splice(revokeIndex, 1);
          } else {
            newUrls[index] = URL.createObjectURL(file);
          }
        } else {
          newUrls[index] = null;
        }
      });

      urlsToRevoke.forEach(url => URL.revokeObjectURL(url));
      return newUrls;
    });
  }, [files]); 

  // Cleanup effect for when the component unmounts
  useEffect(() => {
    return () => {
      fileObjectUrls.forEach(url => {
        if (url) URL.revokeObjectURL(url);
      });
    };
  }, [fileObjectUrls]); 

  const currentFileCount = files.filter(f => f !== null).length;

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>, index: number) => {
    const file = e.target.files?.[0] || null;
    const newFiles = [...files];

    if (newFiles[index] && fileObjectUrls[index]) {
      URL.revokeObjectURL(fileObjectUrls[index]!);
    }

    newFiles[index] = file;
    onFilesChange(category, newFiles); 
    e.target.value = ''; 
  };

  const removeImage = (index: number) => {
    if (fileObjectUrls[index]) {
      URL.revokeObjectURL(fileObjectUrls[index]!); 
    }
    const newFiles = [...files];
    newFiles[index] = null;
    const filteredFiles = newFiles.filter(f => f !== null);
    onFilesChange(category, [...filteredFiles, null, null].slice(0, 3)); 
  };

  const triggerUpload = (index: number) => {
    fileInputRefs.current[index]?.click();
  };

  return (
    <div className="border-2 border-black dark:border-slate-500 bg-white dark:bg-slate-800 p-4 shadow-[4px_4px_0px_0px_rgba(0,0,0,0.1)] group">
      <div className="flex justify-between items-center mb-4 border-l-4 border-blue-600 pl-2">
        <span className="font-black text-xs uppercase tracking-wider dark:text-gray-200">{title}</span>
        <span className="bg-gray-200 dark:bg-slate-700 text-gray-600 dark:text-gray-300 text-[10px] font-bold px-2 py-0.5 rounded-full">{currentFileCount}/3</span>
      </div>
      <div className="grid grid-cols-3 gap-2"> 
        {files.map((file, index) => (
          <div
            key={index}
            className="relative w-full h-24 border-2 border-dashed border-gray-300 dark:border-slate-600 bg-gray-50 dark:bg-slate-700 flex flex-col items-center justify-center text-gray-400 gap-1 cursor-pointer group hover:border-blue-400 hover:text-blue-500 transition-colors overflow-hidden"
            onClick={() => !file && triggerUpload(index)} 
          >
            <input
              type="file"
              ref={el => fileInputRefs.current[index] = el}
              onChange={(e) => handleFileChange(e, index)}
              className="hidden"
              accept="image/*"
              disabled={!!file} 
            />
            {file && fileObjectUrls[index] ? (
              <>
                <img
                  src={fileObjectUrls[index]!} 
                  alt={`Preview ${index}`}
                  className="absolute inset-0 w-full h-full object-cover"
                />
                <button
                  onClick={(e) => { e.stopPropagation(); removeImage(index); }} 
                  className="absolute top-1 right-1 w-5 h-5 rounded-full bg-black/60 hover:bg-black/80 text-white flex items-center justify-center text-xs font-bold transition-all z-10"
                  aria-label={t('remove_image_alt_text')} 
                >
                  &times;
                </button>
              </>
            ) : (
              <>
                <Upload className="w-5 h-5" />
                <span className="text-[10px] font-bold uppercase">{t('box_click')}</span>
              </>
            )}
          </div>
        ))}
      </div>
    </div>
  );
};

