import { GoogleGenAI, Type } from "@google/genai";
import { FormData, PosterMode, AspectRatio, TargetAudience, VisualStyle, CarouselType, Platform, LanguageStyle, PosterLayoutType, ComicContentType } from "../types";
import { translations, Language } from "../translations";

export interface SequentialPrompt {
  title: string;
  content: string;
}

// Helper to sanitize JSON string
const cleanJsonString = (str: string) => {
  return str.replace(/```json\n?|```/g, '').trim();
};

const langNames: Record<string, string> = {
  id: 'Indonesian',
  en: 'English',
  ar: 'Arabic',
  ms: 'Malay',
  zh: 'Chinese',
  ja: 'Japanese'
};

/**
 * Generates a list of unique, sequential prompts based on user input.
 * Adheres strictly to the structural requirements for Comic, Storybook, 
 * and Carousel mode following the latest requested schemas.
 */
export const generateSequentialPrompts = async (formData: FormData, language: Language = 'id'): Promise<SequentialPrompt[]> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const slideCountString = formData.slideCount || '5';
  const slideCount = parseInt(slideCountString.split(' ')[0]) || 5;
  const isComicStripMode = formData.mode === PosterMode.COMIC_STRIP;
  const isStoryBook = formData.comicContentType === ComicContentType.STORY_BOOK;
  const targetLang = langNames[language] || 'Indonesian';

  let systemInstruction = "";

  if (isComicStripMode && isStoryBook) {
    // STORYBOOK MODE - Single Canvas, No Panels
    systemInstruction = `
      You are an expert Storybook Author.
      Task: Generate exactly ${slideCount} sequential pages for a STORYBOOK.
      Format: JSON array of ${slideCount} objects. Each object contains "title" and "content" (stringified JSON).

      STORYBOOK JSON SCHEMA:
      {
        "halaman_ke": number,
        "jenis_halaman": "Cover Storybook" | "Isi Storybook - Pembukaan" | "Isi Storybook - Inti Cerita" | "Penutup Storybook",
        "tipe_konten": "Storybook",
        "alur_cerita": "${formData.storyFlow}",
        "unsur_emosi": "${formData.emotionalElements}",
        "target_audiens": "${formData.targetAudience}",
        "rasio": "${formData.size}",
        "mode_visual": "${formData.visualStyle}",
        "tema_gaya": "${formData.visualTheme}",
        "topik_materi": "${formData.topic}",
        "judul_utama": "${formData.title}",
        "sub_judul": "${formData.subtitle}",
        "isi_materi": "Detailed ${targetLang} script for this page...",
        "deskripsi_visual_utama": "Detailed English visual description (Full canvas illustration, no panels, focusing on theme and mood)...",
        "call_to_action": "${formData.ctaActive ? formData.cta : ''}",
        "fun_fact": "A fascinating and educational fun fact about ${formData.topic} written strictly in ${targetLang}...",
        "identitas_pembuat": "${formData.socialAccount}",
        "watermark": "${formData.watermark}"
      }
    `;
  } else if (isComicStripMode) {
    // COMIC MODE - Panels/Layers for Slide 2+
    systemInstruction = `
      You are an expert Comic Book Creator.
      Task: Generate exactly ${slideCount} sequential pages for a COMIC STRIP.
      Format: JSON array of ${slideCount} objects. Each object contains "title" and "content" (stringified JSON).

      SLIDE 1 (COVER) SCHEMA (MANDATORY STRUCTURE):
      {
        "slide_ke": 1,
        "jenis_slide": "Cover Komik",
        "tipe_konten": "Komik",
        "alur_cerita": "${formData.storyFlow}",
        "unsur_emosi": "${formData.emotionalElements}",
        "target_audiens": "${formData.targetAudience}",
        "topik_materi": "${formData.topic}",
        "judul_utama": "${formData.title}",
        "sub_judul": "${formData.subtitle}",
        "isi_materi": "Title and Credits only in ${targetLang}",
        "rasio": "${formData.size}",
        "mode_visual": "${formData.visualStyle}",
        "tema_gaya": "${formData.visualTheme}",
        "deskripsi_visual": "Ilustrasi cover komik sebagai pembuka cerita. Menampilkan karakter utama atau elemen visual paling representatif dari topik dan tema. Komposisi kuat, fokus di tengah, visual bersih, ekspresif, dan langsung menggambarkan suasana cerita. Tidak menampilkan alur panjang, hanya pengantar visual yang menarik.",
        "struktur_layer": {
          "menggunakan_layer": true,
          "keterangan": "Layer terpisah untuk background, karakter utama, elemen pendukung, dan teks judul."
        },
        "identitas_pembuat": "${formData.socialAccount}",
        "watermark": "${formData.watermark}",
        "negative_prompt": [
          "karakter berbeda di slide berikutnya",
          "perubahan gaya visual",
          "tema tidak konsisten",
          "rasio tidak sesuai",
          "watermark hilang",
          "low quality",
          "blur",
          "distorted anatomy",
          "out of theme"
        ]
      }

      SLIDE 2+ SCHEMA:
      {
        "slide_ke": number,
        "jenis_halaman": "Isi Komik - Pembukaan" | "Isi Komik - Inti Cerita" | "Isi Komik - Penutup",
        "tipe_konten": "Komik",
        "isi_materi": "Script or dialogue for this page in ${targetLang}...",
        "deskripsi_visual": "General mood/setting in English...",
        "panel_komik": {
          "jumlah_panel": 3,
          "detail_panel": [
            "Panel 1: Detailed action in English and dialogue in ${targetLang}...",
            "Panel 2: Detailed action in English and dialogue in ${targetLang}...",
            "Panel 3: Detailed action in English and dialogue in ${targetLang}..."
          ]
        },
        "fun_fact": "A fascinating and educational fun fact about ${formData.topic} written strictly in ${targetLang}...",
        "identitas_pembuat": "${formData.socialAccount}",
        "watermark": "${formData.watermark}"
      }
    `;
  } else {
    // CAROUSEL MODE
    const activeElements = Object.keys(formData.additionalElements)
      .filter(key => formData.additionalElements[key as keyof typeof formData.additionalElements])
      .join(', ');

    systemInstruction = `
      You are a Professional Carousel Designer.
      Task: Generate exactly ${slideCount} sequential slides for a CAROUSEL.
      Format: JSON array of ${slideCount} objects. Each object contains "title" and "content" (stringified JSON).

      CAROUSEL SCHEMA (MANDATORY FOR ALL SLIDES):
      {
        "slide_ke": number,
        "jenis_slide": "Cover Carousel" | "Isi Carousel" | "Penutup Carousel",
        "platform": "${formData.platform}",
        "jumlah_slide": "${formData.slideCount}",
        "gaya_bahasa": "${formData.languageStyle}",
        "tipe_poster": "${formData.posterLayoutType}",
        "target_audiens": "${formData.targetAudience}",
        "topik_materi": "${formData.topic}",
        "judul_utama": "${formData.title}",
        "sub_judul": "${formData.subtitle}",
        "isi_materi": "Specific ${targetLang} text for this slide content...",
        "call_to_action": "${formData.ctaActive ? formData.cta : ''}",
        "fun_fact": "A fascinating and educational fun fact about ${formData.topic} written strictly in ${targetLang}...",
        "identitas_pembuat": "${formData.socialAccount}",
        "watermark": "${formData.watermark}",
        "ukuran_kertas": "${formData.size}",
        "mode_visual": "${formData.visualStyle}",
        "tema_gaya": "${formData.visualTheme}",
        "elemen_tambahan": "${activeElements}",
        "instruksi_tambahan": "${formData.additionalPrompt}"
      }
    `;
  }

  const prompt = `
    ${systemInstruction}

    Current Context:
    - Topic: "${formData.topic}"
    - Title: "${formData.title}"
    - Material Script: "${formData.material}"

    CRITICAL LANGUAGE RULE:
    - All creative text fields (judul_utama, sub_judul, isi_materi, fun_fact, call_to_action) MUST be in ${targetLang}.
    - Only technical AI image prompts (deskripsi_visual, deskripsi_visual_utama, detail_panel visual parts) should be in English.
    - Fun facts MUST ALWAYS match the user's selected language (${targetLang}).
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ text: prompt }],
      config: {
        responseMimeType: 'application/json',
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              title: { type: Type.STRING },
              content: { type: Type.STRING }
            },
            required: ['title', 'content']
          }
        }
      }
    });

    return JSON.parse(response.text);
  } catch (error) {
    console.error("Error generating sequential prompts:", error);
    return Array.from({ length: slideCount }, (_, i) => ({
      title: `Slide ${i + 1}`,
      content: JSON.stringify({ slide_ke: i + 1, judul_utama: formData.title }, null, 2)
    }));
  }
};

export const generateAutoFillContent = async (
  mode: PosterMode | string, 
  currentValues: { 
    topic: string; 
    title: string; 
    subtitle: string; 
    material: string; 
    cta: string;
    targetAudience?: TargetAudience | string; 
    carouselType?: CarouselType; 
    platform?: Platform | string;
    languageStyle?: LanguageStyle | string;
    posterLayoutType?: PosterLayoutType | string;
    additionalElements?: { [key: string]: boolean };
    ctaActive: boolean; 
    funFact: string; 
    funFactActive: boolean; 
    storyFlow?: string; 
    emotionalElements?: string; 
    comicContentType?: ComicContentType;
    slideCount?: string;
  }, 
  context: 'topic' | 'title' | 'subtitle' | 'material' | 'cta' | 'funFact' = 'topic',
  language: Language = 'id'
): Promise<Partial<FormData>> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const t = (key: keyof typeof translations['id']) => {
    return (translations[language] as any)?.[key] || translations['id'][key] || key;
  };

  const targetLang = langNames[language] || 'Indonesian';

  if (context === 'funFact') {
    const topic = currentValues.topic?.trim();
    let basePrompt = "";
    if (topic) {
      basePrompt = t('ph_fun_fact_topic_auto_fill').replace('{topic}', topic);
    } else {
      basePrompt = t('ph_fun_fact_default_auto_fill');
    }

    // Explicitly demand response in the target language
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ text: `${basePrompt}. MANDATORY: Respond with the fun fact text ONLY in ${targetLang} language.` }],
    });
    return { funFact: response.text };
  }

  const isCarouselMode = mode === PosterMode.CAROUSEL;
  const isComicStripMode = mode === PosterMode.COMIC_STRIP;

  let prompt = `
    You are an AI CONTENT ENGINE. Your task is to auto-fill the field [${context}] for a ${mode} project.
    MANDATORY LANGUAGE: All generated content MUST be in ${targetLang}.

    Context:
    - Topic: "${currentValues.topic}"
    - Current Title: "${currentValues.title}"
    - Target Audience: "${currentValues.targetAudience}"
    - Mode specific info: ${isCarouselMode ? `Carousel Type: ${currentValues.carouselType}, Slides: ${currentValues.slideCount}` : `Story Flow: ${currentValues.storyFlow}, Emotion: ${currentValues.emotionalElements}`}
  `;

  if (context === 'material') {
      if (isCarouselMode) {
          prompt += ` Generate a sequential script for ${currentValues.slideCount || '5'} slides using a ${currentValues.carouselType} structure.`;
      } else if (isComicStripMode) {
          prompt += ` Generate a sequential comic script for ${currentValues.slideCount || '5'} panels/pages. Follow a ${currentValues.storyFlow} flow with ${currentValues.emotionalElements} emotions.`;
      }
  }

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [{text: prompt}],
    config: {
      responseMimeType: 'application/json',
      responseSchema: {
          type: Type.OBJECT,
          properties: {
              [context]: { type: Type.STRING, description: `The creative content for the ${context} field in ${targetLang}.` }
          },
          required: [context]
      }
    }
  });

  try {
    return JSON.parse(cleanJsonString(response.text));
  } catch (e) {
    console.error("Failed to parse JSON:", e);
    return {};
  }
};

