export const generateAutoFillContent = async (
  mode: PosterMode | string, 
  currentValues: { 
    topic: string; 
    title: string; 
    subtitle: string; 
    material: string; 
    cta: string;
    targetAudience?: TargetAudience | string; 
    carouselType?: CarouselType; 
    platform?: Platform | string;
    languageStyle?: LanguageStyle | string;
    posterLayoutType?: PosterLayoutType | string;
    additionalElements?: { [key: string]: boolean };
    ctaActive: boolean; 
    funFact: string; 
    funFactActive: boolean; 
    storyFlow?: string; 
    emotionalElements?: string; 
    comicContentType?: ComicContentType;
    slideCount?: string;
  }, 
  context: 'topic' | 'title' | 'subtitle' | 'material' | 'cta' | 'funFact' = 'topic',
  language: Language = 'id'
): Promise<Partial<FormData>> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const t = (key: keyof typeof translations['id']) => {
    return (translations[language] as any)?.[key] || translations['id'][key] || key;
  };

  const targetLang = langNames[language] || 'Indonesian';

  if (context === 'funFact') {
    const topic = currentValues.topic?.trim();
    let basePrompt = "";
    if (topic) {
      basePrompt = t('ph_fun_fact_topic_auto_fill').replace('{topic}', topic);
    } else {
      basePrompt = t('ph_fun_fact_default_auto_fill');
    }

    // Explicitly demand response in the target language
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: [{ text: `${basePrompt}. MANDATORY: Respond with the fun fact text ONLY in ${targetLang} language.` }],
    });
    return { funFact: response.text };
  }

  const isCarouselMode = mode === PosterMode.CAROUSEL;
  const isComicStripMode = mode === PosterMode.COMIC_STRIP;

  let prompt = `
    You are an AI CONTENT ENGINE. Your task is to auto-fill the field [${context}] for a ${mode} project.
    MANDATORY LANGUAGE: All generated content MUST be in ${targetLang}.

    Context:
    - Topic: "${currentValues.topic}"
    - Current Title: "${currentValues.title}"
    - Target Audience: "${currentValues.targetAudience}"
    - Mode specific info: ${isCarouselMode ? `Carousel Type: ${currentValues.carouselType}, Slides: ${currentValues.slideCount}` : `Story Flow: ${currentValues.storyFlow}, Emotion: ${currentValues.emotionalElements}`}
  `;

  if (context === 'material') {
      if (isCarouselMode) {
          prompt += ` Generate a sequential script for ${currentValues.slideCount || '5'} slides using a ${currentValues.carouselType} structure.`;
      } else if (isComicStripMode) {
          prompt += ` Generate a sequential comic script for ${currentValues.slideCount || '5'} panels/pages. Follow a ${currentValues.storyFlow} flow with ${currentValues.emotionalElements} emotions.`;
      }
  }

  const response = await ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: [{text: prompt}],
    config: {
      responseMimeType: 'application/json',
      responseSchema: {
          type: Type.OBJECT,
          properties: {
              [context]: { type: Type.STRING, description: `The creative content for the ${context} field in ${targetLang}.` }
          },
          required: [context]
      }
    }
  });

  try {
    return JSON.parse(cleanJsonString(response.text));
  } catch (e) {
    console.error("Failed to parse JSON:", e);
    return {};
  }
};

